import itertools, json, math, platform, sys
from fractions import Fraction as F

def exact_float(v):
    if type(v) is not float or not math.isfinite(v):
        raise ValueError("finite stored float required")
    return F.from_float(v)

def combined(terms):
    acc={}
    for key,a in terms:
        acc[key]=acc.get(key,F(0))+a
    return {k:a for k,a in acc.items() if a}

def product_hull(c,terms,candidates):
    coeff=combined(terms)
    lower=upper=c
    for key,a in sorted(coeff.items()):
        values=list(candidates[key].values())
        if not values:
            raise ValueError("missing active candidate")
        low,high=min(values),max(values)
        lower+=a*(low if a>0 else high)
        upper+=a*(high if a>0 else low)
    return lower,upper

def oracle_product(c,terms,candidates):
    keys=sorted({key for key,a in terms if a})
    missing={key for key in keys if key not in candidates}
    for key in missing:
        assert sum((a for k,a in terms if k==key),F(0))==0
    keys=[key for key in keys if key not in missing]
    # Oracle evaluates original, uncombined terms using one value per shared key.
    values=[]
    for choices in itertools.product(*(list(candidates[k].values()) for k in keys)):
        assignment=dict(zip(keys,choices))
        values.append(c+sum((a*assignment[k] for k,a in terms if k not in missing),F(0)))
    return min(values),max(values),len(values)

def coherent_hull(c,terms,candidates):
    coeff=combined(terms)
    if not coeff:
        return c,c,["SYMBOLIC_CONSTANT"]
    labels=set.intersection(*(set(candidates[k]) for k in coeff))
    if not labels:
        return None,None,[]
    values=[c+sum((a*candidates[k][label] for k,a in coeff.items()),F(0)) for label in sorted(labels)]
    return min(values),max(values),sorted(labels)

def display(q):
    try:
        f=float(q)
    except OverflowError:
        return {"status":"FINITE_FLOAT_DISPLAY_UNAVAILABLE","exact":str(q)}
    if not math.isfinite(f):
        return {"status":"FINITE_FLOAT_DISPLAY_UNAVAILABLE","exact":str(q)}
    low=math.nextafter(f,-math.inf) if F.from_float(f)>q else f
    high=math.nextafter(f,math.inf) if F.from_float(f)<q else f
    if not math.isfinite(low) or not math.isfinite(high):
        return {"status":"FINITE_FLOAT_DISPLAY_UNAVAILABLE","exact":str(q)}
    assert F.from_float(low)<=q<=F.from_float(high)
    assert low==high or math.nextafter(low,math.inf)==high
    return {"status":"FINITE_OUTWARD_DISPLAY","low_hex":low.hex(),"high_hex":high.hex(),"exact":str(q)}

A={"a":{"Radau":F(100),"DOP853":F(101)},
   "b":{"Radau":F(110),"DOP853":F(111)}}
tests=[]
def record(name,action):
    detail=action()
    tests.append({"case":name,"status":"PASS","detail":detail})
def check_hull(c,terms,candidates,expected=None):
    actual=product_hull(c,terms,candidates)
    oracle=oracle_product(c,terms,candidates)
    assert actual==oracle[:2],(actual,oracle)
    if expected is not None: assert actual==expected
    return {"exact_lower":str(actual[0]),"exact_upper":str(actual[1]),"enumerated_assignments":oracle[2]}

record("repeated_reference_cancellation",lambda:check_hull(F(7),[("a",F(1)),("a",F(-1))],A,(F(7),F(7))))
record("decomposition_shared_reference_cancellation",lambda:check_hull(exact_float(10.25)-exact_float(8.5),[("b",F(1)),("a",F(-1)),("b",F(-1)),("a",F(1))],A,(F(7,4),F(7,4))))
record("signed_coefficient_product_extrema",lambda:check_hull(F(3),[("a",F(-2)),("b",F(3))],A,(F(131),F(136))))
record("duplicate_coefficient_aggregation",lambda:check_hull(F(-2),[("a",F(3,2)),("a",F(-1,2)),("b",F(-1))],A,(F(-13),F(-11))))
record("zero_coefficient_unused_missing_key",lambda:check_hull(F(0),[("absent",F(3)),("absent",F(-3))],{},(F(0),F(0))))
def coherent_strict():
    p=product_hull(F(0),[("b",F(1)),("a",F(-1))],A)
    h=coherent_hull(F(0),[("b",F(1)),("a",F(-1))],A)
    assert p==(F(9),F(11)) and h[:2]==(F(10),F(10))
    return {"product":[str(v) for v in p],"coherent":[str(v) for v in h[:2]],"methods":h[2]}
record("coherent_hull_strict_subset",coherent_strict)
def coherent_anti():
    candidates={"a":{"Radau":F(100),"DOP853":F(101)},"b":{"Radau":F(111),"DOP853":F(110)}}
    terms=[("b",F(1)),("a",F(-1))]
    p=product_hull(F(0),terms,candidates); h=coherent_hull(F(0),terms,candidates)
    assert p==h[:2]==(F(9),F(11))
    return {"product_equals_coherent":True}
record("coherent_hull_can_equal_product",coherent_anti)
def no_common():
    candidates={"a":{"Radau":F(1)},"b":{"DOP853":F(2)}}
    h=coherent_hull(F(0),[("a",F(1)),("b",F(1))],candidates)
    assert h==(None,None,[])
    return {"coherent_status":"UNAVAILABLE","pair_admission_claim":False}
record("missing_common_method_unavailable",no_common)
def three_key():
    candidates={"a":{"Radau":exact_float(0.1),"DOP853":exact_float(0.2)},"b":{"Radau":exact_float(-0.4),"DOP853":exact_float(-0.3)},"c":{"Radau":exact_float(1e-300),"DOP853":exact_float(math.nextafter(1e-300,math.inf))}}
    return check_hull(exact_float(0.1),[("a",F(-3)),("b",F(7,2)),("c",F(-2)),("a",F(1))],candidates)
record("stored_binary64_three_key_extrema",three_key)
def early_rounding():
    a=exact_float(1.0); b=exact_float(0.1)
    exact=a-b; rounded=exact_float(1.0-0.1)
    assert exact!=rounded
    assert b!=F(1,10)
    return {"operands_first_diff":str(exact),"rounded_diff_then_fraction":str(rounded),"equal":False}
record("conversion_before_arithmetic_is_material",early_rounding)
for label,q in [
    ("display_exact_zero",F(0)),
    ("display_exact_binary64",exact_float(0.1)),
    ("display_rational_tenth",F(1,10)),
    ("display_negative_tenth",F(-1,10)),
    ("display_positive_half_min_subnormal",F(1,2**1075)),
    ("display_negative_half_min_subnormal",F(-1,2**1075)),
    ("display_exact_max_finite",exact_float(sys.float_info.max)),
    ("display_nonrepresentable_exact_point",exact_float(1.0)-exact_float(0.1))
]:
    record(label,lambda q=q:display(q))
def overflow():
    d=display(exact_float(sys.float_info.max)*2)
    assert d["status"]=="FINITE_FLOAT_DISPLAY_UNAVAILABLE"
    return {"status":d["status"],"exact_numerator_preserved":True}
record("finite_exact_overflow_rejected_for_float_display",overflow)
def bad_inputs():
    rejected=0
    for v in [float("nan"),float("inf"),float("-inf"),True,"1.0"]:
        try: exact_float(v)
        except ValueError: rejected+=1
    assert rejected==5
    return {"rejected_inputs":rejected}
record("nonfinite_and_nonfloat_stored_value_rejection",bad_inputs)
print(json.dumps({"status":"PASS","independent_theory_checks":len(tests),"runtime":sys.version.split()[0],"implementation":platform.python_implementation(),"float_radix":sys.float_info.radix,"float_mant_dig":sys.float_info.mant_dig,"native_runs":0,"old_tests_run":0,"he29_numeric_results_recomputed":0,"checks":tests},sort_keys=True))
